        with self.assertRaises(ValueError): parse_duration('h')

from solution import merge_intervals
import unittest
class T(unittest.TestCase):
    def test_basic(self): self.assertEqual(merge_intervals([[1,3],[2,6],[8,10],[15,18]]), [[1,6],[8,10],[15,18]])
    def test_touching(self): self.assertEqual(merge_intervals([[1,3],[3,5]]), [[1,5]])
    def test_unsorted(self): self.assertEqual(merge_intervals([[8,10],[1,4],[2,3]]), [[1,4],[8,10]])
    def test_empty(self): self.assertEqual(merge_intervals([]), [])
    def test_contained(self): self.assertEqual(merge_intervals([[1,10],[2,3],[4,5]]), [[1,10]])
    def test_not_mutated(self):
        data = [[5,6],[1,2]]
        merge_intervals(data)
        self.assertEqual(data, [[5,6],[1,2]])

from solution import LRUCache
import unittest
class T(unittest.TestCase):
    def test_evict(self):
        c = LRUCache(2); c.put(1,1); c.put(2,2); self.assertEqual(c.get(1),1); c.put(3,3)
        self.assertEqual(c.get(2),-1); self.assertEqual(c.get(3),3)
    def test_update_counts_as_use(self):
        c = LRUCache(2); c.put(1,1); c.put(2,2); c.put(1,10); c.put(3,3)
        self.assertEqual(c.get(1),10); self.assertEqual(c.get(2),-1)
    def test_missing(self): self.assertEqual(LRUCache(1).get('x'), -1)
    def test_capacity(self):
        with self.assertRaises(ValueError): LRUCache(0)

from solution import int_to_roman
import unittest
class T(unittest.TestCase):
    def test_values(self):
        for n, r in [(1,'I'),(4,'IV'),(9,'IX'),(14,'XIV'),(40,'XL'),(90,'XC'),(400,'CD'),(1994,'MCMXCIV'),(3999,'MMMCMXCIX')]:
            self.assertEqual(int_to_roman(n), r)
    def test_range(self):
        for bad in (0, 4000, -1):
            with self.assertRaises(ValueError): int_to_roman(bad)
    def test_type(self):
        with self.assertRaises(TypeError): int_to_roman(2.5)
        with self.assertRaises(TypeError): int_to_roman(True)

